function wikiInstantDriveType_(mimeType,fileName){mimeType=String(mimeType||"");fileName=String(fileName||"");const map={};map[MimeType.GOOGLE_DOCS]={type:"doc",label:"Google Docs",family:"document",supported:true};map[MimeType.GOOGLE_SHEETS]={type:"sheet",label:"Google Sheets",family:"sheet",supported:true};map[MimeType.PDF]={type:"pdf",label:"PDF",family:"document",supported:true,convertTo:"doc"};map["text/html"]={type:"html",label:"HTML",family:"document",supported:true,convertTo:"doc"};map["application/xhtml+xml"]={type:"html",label:"HTML",family:"document",supported:true,convertTo:"doc"};map["application/vnd.openxmlformats-officedocument.wordprocessingml.document"]={type:"word",label:"Word",family:"document",supported:true,convertTo:"doc"};map["application/msword"]={type:"word",label:"Word",family:"document",supported:true,convertTo:"doc"};map["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]={type:"excel",label:"Excel",family:"sheet",supported:true,convertTo:"sheet"};map["application/vnd.ms-excel"]={type:"excel",label:"Excel",family:"sheet",supported:true,convertTo:"sheet"};map["application/vnd.oasis.opendocument.spreadsheet"]={type:"ods",label:"OpenDocument-regneark",family:"sheet",supported:true,convertTo:"sheet"};map["text/csv"]={type:"csv",label:"CSV",family:"sheet",supported:true,convertTo:"sheet"};map["text/tab-separated-values"]={type:"tsv",label:"TSV",family:"sheet",supported:true,convertTo:"sheet"};if(map[mimeType])return map[mimeType];const lower=fileName.toLowerCase();if(/\.docx?$/.test(lower))return{type:"word",label:"Word",family:"document",supported:true,convertTo:"doc"};if(/\.pdf$/.test(lower))return{type:"pdf",label:"PDF",family:"document",supported:true,convertTo:"doc"};if(/\.html?$/.test(lower))return{type:"html",label:"HTML",family:"document",supported:true,convertTo:"doc"};if(/\.csv$/.test(lower))return{type:"csv",label:"CSV",family:"sheet",supported:true,convertTo:"sheet"};if(/\.tsv$/.test(lower))return{type:"tsv",label:"TSV",family:"sheet",supported:true,convertTo:"sheet"};if(/\.ods$/.test(lower))return{type:"ods",label:"OpenDocument-regneark",family:"sheet",supported:true,convertTo:"sheet"};if(/\.xlsx?$/.test(lower))return{type:"excel",label:"Excel",family:"sheet",supported:true,convertTo:"sheet"};return null}

