function wikiInstantRenderTextElement_(textEl){const raw=String(textEl&&textEl.getText?textEl.getText():"");if(!raw)return"";let indices=[0];try{const found=textEl.getTextAttributeIndices();if(found&&found.length)indices=found}catch(ignored){}const out=[];for(let i=0;i<indices.length;i+=1){const start=indices[i];const end=i+1<indices.length?indices[i+1]:raw.length;const rawPart=raw.substring(start,end);if(!rawPart)continue;let part=wikiInstantEscapeInlineText_(rawPart).replace(/\n/g,"<br>");let attrs={};try{attrs=textEl.getAttributes(start)||{}}catch(ignored){}let link="";try{link=String(textEl.getLinkUrl(start)||"")}catch(ignored){}const bold=attrs[HUDocumentApp.Attribute.BOLD]===true;const italic=attrs[HUDocumentApp.Attribute.ITALIC]===true;const underline=attrs[HUDocumentApp.Attribute.UNDERLINE]===true;const strike=attrs[HUDocumentApp.Attribute.STRIKETHROUGH]===true;if(bold)part="''"+part+"''";if(italic)part="//"+part+"//";if(strike)part="<s>"+part+"</s>";if(link){const safeLink=link.replace(/\]/g,"%5D").replace(/\|/g,"%7C");const rawLabel=rawPart.replace(/\s+/g," ").trim();part=rawLabel===link?"[ext["+safeLink+"]]":"[ext["+part+"|"+safeLink+"]]"}else if(underline){part="<u>"+part+"</u>"}out.push(part)}return out.join("")}

function wikiInstantRenderContainerInline_(container){if(!container)return"";const out=[];try{for(let i=0;i<container.getNumChildren();i+=1){const child=container.getChild(i);const type=child.getType();if(type===HUDocumentApp.ElementType.TEXT){out.push(wikiInstantRenderTextElement_(child.asText()))}else if(type===HUDocumentApp.ElementType.INLINE_IMAGE){out.push("🖼 ''Billede fra kildedokument''")}}}catch(ignored){try{return wikiInstantEscapeInlineText_(container.getText())}catch(ignored2){}}try{if(typeof container.getPositionedImages==="function"){const positioned=container.getPositionedImages();if(positioned&&positioned.length){for(let p=0;p<positioned.length;p+=1){out.push(" 🖼 ''Billede fra kildedokument''")}}}}catch(ignored){}return out.join("")}

function wikiInstantRenderTableCell_(cell){const parts=[];try{for(let i=0;i<cell.getNumChildren();i+=1){const child=cell.getChild(i);const type=child.getType();if(type===HUDocumentApp.ElementType.PARAGRAPH){const value=wikiInstantRenderContainerInline_(child.asParagraph()).trim();if(value)parts.push(value)}else if(type===HUDocumentApp.ElementType.LIST_ITEM){const value=wikiInstantRenderContainerInline_(child.asListItem()).trim();if(value)parts.push(value)}else if(type===HUDocumentApp.ElementType.TABLE){const value=wikiInstantTableText_(child.asTable());if(value)parts.push(value.replace(/\n/g,"<br>"))}}}catch(ignored){try{parts.push(wikiInstantEscapeInlineText_(cell.getText()))}catch(ignored2){}}return parts.join("<br>")}

function wikiInstantTableText_(table){const lines=[];try{for(let r=0;r<table.getNumRows();r+=1){const row=table.getRow(r);const cells=[];for(let c=0;c<row.getNumCells();c+=1){cells.push(wikiInstantRenderTableCell_(row.getCell(c)))}if(!cells.length)continue;lines.push("|"+cells.join("|")+"|"+(r===0?"h":""))}}catch(ignored){}return lines.join("\n")}

function wikiInstantCountImagesInElement_(element){if(!element)return 0;let count=0;try{if(element.getType&&element.getType()===HUDocumentApp.ElementType.INLINE_IMAGE){count+=1}}catch(ignored){}try{if(typeof element.getPositionedImages==="function"){const positioned=element.getPositionedImages();if(positioned&&positioned.length)count+=positioned.length}}catch(ignored){}try{if(typeof element.getNumChildren==="function"){for(let i=0;i<element.getNumChildren();i+=1){count+=wikiInstantCountImagesInElement_(element.getChild(i))}}}catch(ignored){}return count}

function wikiInstantProgressKey_(jobId){return"instant-progress:"+String(jobId||"").replace(/[^A-Za-z0-9_.:-]/g,"").substring(0,120)}

