function huInstantGetProgress(jobId){jobId=String(jobId||"");if(!jobId)return{ok:false};try{const raw=CacheService.getUserCache().get(wikiInstantProgressKey_(jobId));if(!raw)return{ok:true,pending:true};return JSON.parse(raw)}catch(err){return{ok:false,message:err&&err.message?err.message:String(err)}}}

function wikiInstantTitleFromPlainText_(value,fallback){let text=String(value==null?"":value).replace(/\s+/g," ").replace(/^[\s\-–—•*#]+|[\s:;,.!?\-–—]+$/g,"").trim();if(!text)return String(fallback||"Afsnit");const words=text.split(" ");if(words.length>9)text=words.slice(0,9).join(" ")+"…";if(text.length>72)text=text.substring(0,69).trim()+"…";return text||String(fallback||"Afsnit")}

function wikiInstantBoldLead_(paragraph){if(!paragraph)return"";try{for(let c=0;c<paragraph.getNumChildren();c+=1){const child=paragraph.getChild(c);if(child.getType()!==HUDocumentApp.ElementType.TEXT)continue;const textEl=child.asText();const raw=String(textEl.getText()||"");if(!raw.trim())continue;let started=false;let out="";for(let i=0;i<raw.length;i+=1){const ch=raw.charAt(i);let attrs={};try{attrs=textEl.getAttributes(i)||{}}catch(ignored){}const bold=attrs[HUDocumentApp.Attribute.BOLD]===true;if(!started){if(/\s/.test(ch))continue;if(!bold)return"";started=true}if(!bold&&!/\s/.test(ch))break;out+=ch}out=out.replace(/\s+/g," ").trim();if(out.length>=3&&out.length<=110)return out;return""}}catch(ignored){}return""}

function wikiInstantIsSoftHeading_(paragraph,plainText,boldLead){plainText=String(plainText||"").trim();boldLead=String(boldLead||"").trim();if(!plainText||plainText.length>130||!boldLead)return false;const normalizedText=plainText.replace(/\s+/g," ").trim();const normalizedBold=boldLead.replace(/\s+/g," ").trim();return normalizedBold.length>=Math.max(4,Math.floor(normalizedText.length*.82))}

