function wikiInstantBoldLeadStartsSection_(plainText,boldLead,hasGap){const text=String(plainText||"").replace(/\s+/g," ").trim();const lead=String(boldLead||"").replace(/\s+/g," ").trim();if(!text||!lead||lead.length<4)return false;if(lead.length>=Math.max(4,Math.floor(text.length*.82)))return false;if(lead.length>=10)return true;if(hasGap&&/[:：.;!?]\s*$/.test(lead))return true;return false}

