function wikiInstantConvertDriveFile_(file,targetMimeType,options){options=options||{};const boundary="wiki_import_"+Utilities.getUuid().replace(/-/g,"");let blob;try{blob=file.getBlob()}catch(err){throw new Error("Filen kunne ikke læses fra Drev. Kontrollér at den kan downloades, og prøv igen.")}const metadata={name:"Wiki import – "+String(file.getName()||"Dokument")+" – "+Utilities.getUuid().substring(0,8),mimeType:String(targetMimeType)};const head=["--"+boundary+"\r\n","Content-Type: application/json; charset=UTF-8\r\n\r\n",JSON.stringify(metadata),"\r\n--"+boundary+"\r\n","Content-Type: "+String(options.contentType||blob.getContentType()||file.getMimeType()||"application/octet-stream")+"\r\n\r\n"].join("");const tail="\r\n--"+boundary+"--\r\n";const bytes=wikiInstantConcatBytes_(wikiInstantStringBytes_(head),blob.getBytes(),wikiInstantStringBytes_(tail));let url="https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,mimeType,webViewLink&supportsAllDrives=true&ignoreDefaultVisibility=true";if(options.ocrLanguage)url+="&ocrLanguage="+encodeURIComponent(String(options.ocrLanguage));const response=UrlFetchApp.fetch(url,{method:"post",headers:{Authorization:"Bearer "+ScriptApp.getOAuthToken()},contentType:"multipart/related; boundary="+boundary,payload:bytes,muteHttpExceptions:true});const code=Number(response.getResponseCode());const body=String(response.getContentText()||"");if(code<200||code>=300){let detail=body;try{const parsed=JSON.parse(body);detail=parsed&&parsed.error&&parsed.error.message?parsed.error.message:body}catch(ignored){}throw new Error("Google Drev kunne ikke konvertere filen: "+String(detail||"HTTP "+code).substring(0,280))}const created=JSON.parse(body||"{}");if(!created.id)throw new Error("Google Drev returnerede ingen konverteret fil.");return created}

