function wikiInstantSheetHeaders_(row,width){const used=Object.create(null);const headers=[];for(let c=0;c<width;c+=1){let label=String(row&&row[c]||"").replace(/\s+/g," ").trim();if(!label)label="Kolonne "+wikiInstantColumnName_(c);let unique=label;let n=2;while(used[unique.toLowerCase()]){unique=label+" ("+n+")";n+=1}used[unique.toLowerCase()]=true;headers.push({index:c,label:unique,column:wikiInstantColumnName_(c)})}return headers}

