function wikiInstantChooseTitleColumn_(headers,rows){const preferred=/^(titel|title|navn|name|emne|overskrift|id|nr\.?|nummer)$/i;for(let i=0;i<headers.length;i+=1){if(preferred.test(String(headers[i].label||"").trim()))return i}for(let c=0;c<headers.length;c+=1){const seen=Object.create(null);let nonEmpty=0,unique=0;for(let r=0;r<Math.min(rows.length,80);r+=1){const value=String(rows[r]&&rows[r][c]||"").trim();if(!value)continue;nonEmpty+=1;if(!seen[value]){seen[value]=true;unique+=1}}if(nonEmpty>=2&&unique/nonEmpty>=.7)return c}return 0}

