function huInstantImportDriveToWiki(payload){payload=payload||{};const started=Date.now();const fileId=String(payload.fileId||"").trim();const wikiId=String(payload.wikiId||"").trim();const jobId=String(payload.jobId||"").trim();if(!fileId)throw new Error("Vælg et dokument først.");if(!wikiId)throw new Error("Vælg en destinationswiki først.");wikiInstantSetProgress_(jobId,{stage:"analyse",percent:4,message:"Analyserer dokumentet…"});const parseOptions=wikiInstantParseOptionsFromPayload_(payload);const parsed=wikiInstantParseDriveSource_(fileId,parseOptions);const plan=Array.isArray(payload.sectionPlan)?payload.sectionPlan:(parsed.sections||[]).map(function(section,index){return{index:index,splitBefore:true,title:section.title}});const selected=wikiInstantApplySectionPlan_(parsed.sections,plan);if(!selected.length)throw new Error("Dokumentet indeholder ingen dele.");wikiInstantSetProgress_(jobId,{stage:"import",percent:10,current:0,total:selected.length,message:"Forbereder "+selected.length+" dokumentdele til wikien…"});const documentLabel=String(payload.documentTitle||parsed.file.name||"Dokument").trim()||"Dokument";const documentTag=wikiInstantNormaliseDocumentTag_(payload.documentTag,documentLabel);wikiPlaceUploadedSource_(fileId,wikiId);const imported=wikiInstantWriteImportedTiddlers_(wikiId,documentLabel,parsed.file,selected,jobId,documentTag);const elapsedMs=Date.now()-started;const url=wikiAppUrl_()+"?wiki="+encodeURIComponent(wikiId)+"&tiddler="+encodeURIComponent(imported.documentTitle||documentLabel);wikiInstantSetProgress_(jobId,{stage:"done",percent:100,current:imported.documentPartCount,total:imported.documentPartCount,message:"Dokumentet er importeret – åbner wikien…",done:true,url:url});return{ok:true,wikiId:wikiId,title:documentLabel,documentTitle:imported.documentTitle,url:url,tiddlerCount:imported.count,documentPartCount:imported.documentPartCount,elapsedMs:elapsedMs,splitMode:parsed.modeUsed}}

function huInstantCreateWikiFromDrive(payload){payload=payload||{};const fileId=String(payload.fileId||"");const jobId=String(payload.jobId||"");if(!fileId)throw new Error("Vælg et dokument først.");const started=Date.now();wikiInstantSetProgress_(jobId,{stage:"analyse",percent:4,message:"Analyserer dokumentet…"});const parseOptions=wikiInstantParseOptionsFromPayload_(payload);const parsed=wikiInstantParseDriveSource_(fileId,parseOptions);const plan=Array.isArray(payload.sectionPlan)?payload.sectionPlan:Array.isArray(payload.selectedSections)?payload.selectedSections.map(function(item){return{index:item.index,title:item.title,splitBefore:true}}):[];const selected=wikiInstantApplySectionPlan_(parsed.sections,plan);if(!selected.length)throw new Error("Dokumentet indeholder ingen tekst, der kan importeres.");const wikiTitle=String(payload.wikiTitle||parsed.file.name||"Instant Wiki").trim()||"Instant Wiki";wikiInstantSetProgress_(jobId,{stage:"create",percent:10,current:0,total:selected.length,message:"Opretter wiki til "+selected.length+" dokumentdele…"});try{const documentTag=wikiInstantNormaliseDocumentTag_(payload.documentTag,parsed.file.name||wikiTitle);const created=wikiInstantCreateDirect_(wikiTitle,parsed.file,selected,jobId,documentTag,payload.language);wikiPlaceUploadedSource_(fileId,created.wikiId);const elapsedMs=Date.now()-started;wikiInstantSetProgress_(jobId,{stage:"done",percent:100,current:created.tiddlerCount,total:created.tiddlerCount,message:"Klar på "+Math.max(1,Math.round(elapsedMs/1e3))+" sek. – åbner wikien…",done:true,elapsedMs:elapsedMs});return Object.assign({},created,{sourceFileId:parsed.file.id,elapsedMs:elapsedMs,splitMode:parsed.modeUsed})}catch(err){wikiInstantSetProgress_(jobId,{stage:"error",percent:100,message:err&&err.message?err.message:"Instant Wiki mislykkedes.",error:true});throw err}}
